1	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
2	import { getJson, postJson } from '../../api/http';
3	
4	// An invoice raised on a project. Everything that shows a project's invoices shares the key
5	// ['invoices', projectId]; invalidating it after a write refreshes the list and its total together.
6	export type Invoice = {
7	  id: number;
8	  projectId: number;
9	  amount: number;
10	  status: string;
11	  issuedDate: string;
12	  dueDate: string;
13	};
14	
15	export const invoicesKey = (projectId: number) => ['invoices', projectId] as const;
16	
17	// How a project's invoices are ordered. 'due' asks the server for earliest due date first; any other
18	// value keeps the default id order. The sort is part of the query key (as a suffix under the shared
19	// ['invoices', projectId] prefix) so each ordering caches on its own, while a write still invalidates
20	// the whole prefix and refreshes every ordering at once.
21	export function useInvoices(projectId: number, sort: string = 'id') {
22	  return useQuery({
23	    queryKey: [...invoicesKey(projectId), sort],
24	    queryFn: () => getJson<Invoice[]>(`/api/invoices?projectId=${projectId}&sort=${sort}`),
25	  });
26	}
27	
28	export function useCreateInvoice(projectId: number) {
29	  const queryClient = useQueryClient();
30	  return useMutation({
31	    mutationFn: (input: { amount: number }) =>
32	      postJson<Invoice>('/api/invoices', { projectId, amount: input.amount }),
33	    onSuccess: () => queryClient.invalidateQueries({ queryKey: invoicesKey(projectId) }),
34	  });
35	}
36	
37	// Mark an invoice paid: POSTs {id} and invalidates ['invoices', projectId] so the list reflects the
38	// new status from the server. The server also keeps an audit record of every payment.
39	export function usePayInvoice(projectId: number) {
40	  const queryClient = useQueryClient();
41	  return useMutation({
42	    mutationFn: (input: { id: number }) =>
43	      postJson<Invoice>('/api/invoices/pay', { id: input.id }),
44	    onSuccess: () => queryClient.invalidateQueries({ queryKey: invoicesKey(projectId) }),
45	  });
46	}
